import{G as e,W as t,n,rt as r}from"./chunks/framework.OKfwtFe7.js";var i=JSON.parse(`{"title":"远程外观与数据传输对象（Remote Facade and Data Transfer Object）","description":"","frontmatter":{},"headers":[],"relativePath":"structural/remote-facade.md","filePath":"structural/remote-facade.md","lastUpdated":1791593218000}`),a={name:`structural/remote-facade.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="远程外观与数据传输对象-remote-facade-and-data-transfer-object" tabindex="-1">远程外观与数据传输对象（Remote Facade and Data Transfer Object） <a class="header-anchor" href="#远程外观与数据传输对象-remote-facade-and-data-transfer-object" aria-label="Permalink to “远程外观与数据传输对象（Remote Facade and Data Transfer Object）”">​</a></h1><p>把领域对象的方法直接摆上网络边界，客户端每读一个字段就是一次往返，服务端的内部结构也被迫冻结——远程外观给出的解法是：边界上不放对象，放一个按用例切分的粗粒度接口，接口的参数和返回值是专用的传输对象。两个概念出自 Fowler 的《企业应用架构模式》[S5]，前者在&quot;分布&quot;一组，后者是跨边界的纯数据载体，通常成对出现。</p><p>站内口径（这一篇与<a href="/hello-design-patterns/structural/remote-proxy">远程代理</a>的分工，也是它成立的前提）：</p><ul><li><strong>远程代理管&quot;透明&quot;</strong>：客户端以为在调本地对象，粒度跟着对象接口走，网络细节由代理吞掉。</li><li><strong>远程外观管&quot;边界&quot;</strong>：不追求透明，明说这是服务接口，方法按业务用例设计（<code>PlaceOrder</code> 而不是 <code>setCustomerName</code>），粒度由调用代价决定。</li></ul><p>远程调用不是方法调用——一次往返有延迟、会失败、要计费。透明性在跨进程时是负债：它鼓励细粒度调用，而细粒度调用在本地是免费的、在网络上是灾难。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to “机制”">​</a></h2><p>两层结构，各管一件事：</p><div class="language- line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki github-dark" style="background-color:#24292e;color:#e1e4e8;" tabindex="0" dir="ltr"><code><span class="line"><span>客户端 ──► OrderFacade.PlaceOrder(req PlaceOrderRequest)</span></span>
<span class="line"><span>                 │            └── DTO：只带这次用例需要的字段</span></span>
<span class="line"><span>                 ▼</span></span>
<span class="line"><span>        仓储 / 支付 / 库存（领域对象不出边界）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><ul><li><strong>外观定接口</strong>：方法对应一个业务用例，一次调用完成一件事。事务边界、鉴权点、限流点都落在这里——它们都需要&quot;一次调用=一次业务动作&quot;的语义，细粒度对象接口给不了。</li><li><strong>DTO 定载荷</strong>：请求和响应各是一个扁平结构，只放这次用例要的字段。领域对象（聚合、懒加载关联、业务方法）留在服务端内部，边界两侧各自演化。</li></ul><p>DTO 与领域对象分离的三个直接收益：</p><ol><li><strong>版本自由</strong>：内部模型重构不改 API；给 DTO 加字段是兼容变更，改领域对象的字段名不是。</li><li><strong>裁剪即安全</strong>：字段按用例需要白名单式给出，不会把内部标识、敏感字段顺着序列化漏出去。</li><li><strong>序列化可控</strong>：扁平结构对 JSON、Protobuf、gRPC 都友好；带对象图和循环引用的领域模型不是。</li></ol><h2 id="适用与不适用" tabindex="-1">适用与不适用 <a class="header-anchor" href="#适用与不适用" aria-label="Permalink to “适用与不适用”">​</a></h2><p>适用于：</p><ol><li>跨进程的服务接口（HTTP API、gRPC service）——只要调用要过网络，粗粒度外观就是默认选项。</li><li>领域模型复杂、客户端多样的系统——Web、移动端、第三方对接各要各的字段，DTO 按客户端裁剪，领域模型保持一份。</li><li>需要在边界上集中事务、鉴权、限流的系统——这些横切逻辑要挂在&quot;用例&quot;粒度上，外观是天然的挂点。</li></ol><p>不适用的三种：</p><ol><li><strong>进程内调用</strong>：没有网络代价，直接用领域接口，加外观只是白传一层（进程内的简化入口是<a href="/hello-design-patterns/structural/facade">外观模式</a>）。</li><li><strong>透传式网关</strong>：只是转发请求、不聚合不裁剪，那是<a href="/hello-design-patterns/structural/remote-proxy">远程代理</a>或负载均衡的活，写成外观是给管道加法兰。</li><li><strong>CRUD 直通</strong>：没有领域规则的资源增删改查，控制器直接操作数据源即可，套外观加 DTO 是给管道加两处法兰。</li></ol><h2 id="与其他模式的关系" tabindex="-1">与其他模式的关系 <a class="header-anchor" href="#与其他模式的关系" aria-label="Permalink to “与其他模式的关系”">​</a></h2><ul><li>与<a href="/hello-design-patterns/structural/remote-proxy">远程代理</a>：同一个&quot;跨进程&quot;场景的两种取向。代理保透明、粒度跟对象；外观弃透明、粒度跟用例。对外观良好的服务接口，客户端代码读起来像本地方法调用，但签名是业务动作而不是对象 getter。</li><li>与<a href="/hello-design-patterns/structural/facade">外观模式</a>：同一意图的进程内版本。远程外观多出来的东西——DTO、序列化、版本、超时与重试的挂点——全部来自&quot;跨了进程&quot;这一事实。</li><li>与<a href="/hello-design-patterns/other/repository">仓储与单元工作</a>：仓储返回领域对象，DTO 的转换发生在边界（外观或控制器），别让 DTO 从仓储里出来——那会把接口层的裁剪需求压进领域层。</li><li>与<a href="/hello-design-patterns/anti-patterns/anemic-domain-model">贫血模型</a>：DTO 天然贫血，这是对的——它是数据载体不是模型。危险的是把 DTO 当领域模型用：规则散落在转换代码里，&quot;金额不能为负&quot;校验三处重复。贫血的反面教材，见反模式篇。</li><li>与<a href="/hello-design-patterns/other/transaction-script">事务脚本</a>：外观的一个方法常和事务脚本的一个流程一一对应；复杂到需要聚合与不变量时，外观内部走领域模型，外观本身不变。</li><li>与<a href="/hello-design-patterns/other/event-sourcing">事件溯源</a>：事件是另一种跨边界载荷——记&quot;发生了什么&quot;而不是&quot;当前长什么样&quot;，与 DTO 互补而非替代。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to “示例”">​</a></h2><p>Go 实现：外观暴露用例级方法，参数与返回值是 DTO，领域对象不越过边界。</p><div class="language-go line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">go</span><pre class="shiki github-dark" style="background-color:#24292e;color:#e1e4e8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#818e99;">// facade/dto.go —— 边界载荷：扁平、只含用例需要的字段</span></span>
<span class="line"><span style="color:#F97583;">package</span><span style="color:#B392F0;"> facade</span></span>
<span class="line"></span>
<span class="line"><span style="color:#F97583;">import</span><span style="color:#9ECBFF;"> &quot;</span><span style="color:#B392F0;">time</span><span style="color:#9ECBFF;">&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#F97583;">type</span><span style="color:#B392F0;"> PlaceOrderRequest</span><span style="color:#F97583;"> struct</span><span style="color:#E1E4E8;"> {</span></span>
<span class="line"><span style="color:#E1E4E8;">	UserID    </span><span style="color:#F97583;">int64</span></span>
<span class="line"><span style="color:#E1E4E8;">	ItemID    </span><span style="color:#F97583;">int64</span></span>
<span class="line"><span style="color:#E1E4E8;">	Quantity  </span><span style="color:#F97583;">int</span></span>
<span class="line"><span style="color:#E1E4E8;">	PaymentID </span><span style="color:#F97583;">string</span></span>
<span class="line"><span style="color:#E1E4E8;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#F97583;">type</span><span style="color:#B392F0;"> PlaceOrderResponse</span><span style="color:#F97583;"> struct</span><span style="color:#E1E4E8;"> {</span></span>
<span class="line"><span style="color:#E1E4E8;">	OrderID   </span><span style="color:#F97583;">int64</span></span>
<span class="line"><span style="color:#E1E4E8;">	PlacedAt  </span><span style="color:#B392F0;">time</span><span style="color:#E1E4E8;">.</span><span style="color:#B392F0;">Time</span></span>
<span class="line"><span style="color:#E1E4E8;">	Charged   </span><span style="color:#F97583;">bool</span></span>
<span class="line"><span style="color:#E1E4E8;">	Message   </span><span style="color:#F97583;">string</span></span>
<span class="line"><span style="color:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br></div></div><div class="language-go line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">go</span><pre class="shiki github-dark" style="background-color:#24292e;color:#e1e4e8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#818e99;">// facade/order.go —— 外观：一次调用一个用例，横切逻辑挂在这里</span></span>
<span class="line"><span style="color:#F97583;">package</span><span style="color:#B392F0;"> facade</span></span>
<span class="line"></span>
<span class="line"><span style="color:#F97583;">import</span><span style="color:#E1E4E8;"> (</span></span>
<span class="line"><span style="color:#9ECBFF;">	&quot;</span><span style="color:#B392F0;">context</span><span style="color:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="color:#9ECBFF;">	&quot;</span><span style="color:#B392F0;">fmt</span><span style="color:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="color:#E1E4E8;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#F97583;">type</span><span style="color:#B392F0;"> OrderFacade</span><span style="color:#F97583;"> struct</span><span style="color:#E1E4E8;"> {</span></span>
<span class="line"><span style="color:#E1E4E8;">	orders    </span><span style="color:#B392F0;">OrderRepo</span><span style="color:#818e99;">    // 领域层仓储，返回领域对象</span></span>
<span class="line"><span style="color:#E1E4E8;">	payments  </span><span style="color:#B392F0;">PaymentClient</span></span>
<span class="line"><span style="color:#E1E4E8;">	inventory </span><span style="color:#B392F0;">StockClient</span></span>
<span class="line"><span style="color:#E1E4E8;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#818e99;">// PlaceOrder 一个方法 = 一个业务用例 = 一个事务边界。</span></span>
<span class="line"><span style="color:#818e99;">// 领域对象 Order 全程不出这个包，外面只见 DTO。</span></span>
<span class="line"><span style="color:#F97583;">func</span><span style="color:#E1E4E8;"> (</span><span style="color:#FFAB70;">f </span><span style="color:#F97583;">*</span><span style="color:#B392F0;">OrderFacade</span><span style="color:#E1E4E8;">) </span><span style="color:#B392F0;">PlaceOrder</span><span style="color:#E1E4E8;">(</span><span style="color:#FFAB70;">ctx</span><span style="color:#B392F0;"> context</span><span style="color:#E1E4E8;">.</span><span style="color:#B392F0;">Context</span><span style="color:#E1E4E8;">, </span><span style="color:#FFAB70;">req</span><span style="color:#B392F0;"> PlaceOrderRequest</span><span style="color:#E1E4E8;">) (</span><span style="color:#B392F0;">PlaceOrderResponse</span><span style="color:#E1E4E8;">, </span><span style="color:#F97583;">error</span><span style="color:#E1E4E8;">) {</span></span>
<span class="line"><span style="color:#F97583;">	if</span><span style="color:#E1E4E8;"> err </span><span style="color:#F97583;">:=</span><span style="color:#E1E4E8;"> f.payments.</span><span style="color:#B392F0;">Charge</span><span style="color:#E1E4E8;">(ctx, req.PaymentID, req.ItemID, req.Quantity); err </span><span style="color:#F97583;">!=</span><span style="color:#79B8FF;"> nil</span><span style="color:#E1E4E8;"> {</span></span>
<span class="line"><span style="color:#F97583;">		return</span><span style="color:#B392F0;"> PlaceOrderResponse</span><span style="color:#E1E4E8;">{}, fmt.</span><span style="color:#B392F0;">Errorf</span><span style="color:#E1E4E8;">(</span><span style="color:#9ECBFF;">&quot;payment: </span><span style="color:#79B8FF;">%w</span><span style="color:#9ECBFF;">&quot;</span><span style="color:#E1E4E8;">, err)</span></span>
<span class="line"><span style="color:#E1E4E8;">	}</span></span>
<span class="line"><span style="color:#E1E4E8;">	order, err </span><span style="color:#F97583;">:=</span><span style="color:#E1E4E8;"> f.orders.</span><span style="color:#B392F0;">Place</span><span style="color:#E1E4E8;">(ctx, req.UserID, req.ItemID, req.Quantity)</span></span>
<span class="line"><span style="color:#F97583;">	if</span><span style="color:#E1E4E8;"> err </span><span style="color:#F97583;">!=</span><span style="color:#79B8FF;"> nil</span><span style="color:#E1E4E8;"> {</span></span>
<span class="line"><span style="color:#E1E4E8;">		f.payments.</span><span style="color:#B392F0;">Refund</span><span style="color:#E1E4E8;">(ctx, req.PaymentID) </span><span style="color:#818e99;">// 补偿，仍留在外观这一层</span></span>
<span class="line"><span style="color:#F97583;">		return</span><span style="color:#B392F0;"> PlaceOrderResponse</span><span style="color:#E1E4E8;">{}, err</span></span>
<span class="line"><span style="color:#E1E4E8;">	}</span></span>
<span class="line"><span style="color:#F97583;">	return</span><span style="color:#B392F0;"> PlaceOrderResponse</span><span style="color:#E1E4E8;">{ </span><span style="color:#818e99;">// 转换在边界做，按白名单取字段</span></span>
<span class="line"><span style="color:#E1E4E8;">		OrderID:  order.ID,</span></span>
<span class="line"><span style="color:#E1E4E8;">		PlacedAt: order.PlacedAt,</span></span>
<span class="line"><span style="color:#E1E4E8;">		Charged:  </span><span style="color:#79B8FF;">true</span><span style="color:#E1E4E8;">,</span></span>
<span class="line"><span style="color:#E1E4E8;">		Message:  </span><span style="color:#9ECBFF;">&quot;ok&quot;</span><span style="color:#E1E4E8;">,</span></span>
<span class="line"><span style="color:#E1E4E8;">	}, </span><span style="color:#79B8FF;">nil</span></span>
<span class="line"><span style="color:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br></div></div><p>Java 侧不必自己写：Spring MVC 的 <code>@RestController</code> 方法签名（<code>@RequestBody PlaceOrderRequest</code> 进、<code>Response</code> 出）就是远程外观的标准形态，EJB 时代的 Session Facade 是它的前身；gRPC/Protobuf 的 <code>message</code> 定义就是 DTO——<code>protoc</code> 生成的类天然扁平、带版本兼容规则。</p><h2 id="接入时的三件小事" tabindex="-1">接入时的三件小事 <a class="header-anchor" href="#接入时的三件小事" aria-label="Permalink to “接入时的三件小事”">​</a></h2><ol><li><strong>方法按用例命名</strong>：签名里出现 <code>setXxx</code>/<code>getXxx</code> 时先停下——细粒度正往回爬，问自己这个调用能不能合并成一个业务动作。</li><li><strong>DTO 单独定义，别直接用领域对象</strong>：一次&quot;图省事&quot;会让 API 签名和内部模型焊死，之后每次重构都是破坏性变更。</li><li><strong>转换只在边界做一次</strong>：外观或控制器里 DTO↔领域对象单点转换；转换逻辑散到多处，字段裁剪就再也没有单一事实源。</li></ol><h2 id="相关篇目" tabindex="-1">相关篇目 <a class="header-anchor" href="#相关篇目" aria-label="Permalink to “相关篇目”">​</a></h2><ul><li><a href="/hello-design-patterns/structural/remote-proxy">远程代理模式</a>：跨进程的透明取向，与本篇的边界取向互为对照。</li><li><a href="/hello-design-patterns/structural/facade">外观模式</a>：进程内版本，同名意图的不同作用域。</li><li><a href="/hello-design-patterns/other/repository">仓储与单元工作</a>：外观编排的下层，DTO 不从仓储出来。</li><li><a href="/hello-design-patterns/anti-patterns/anemic-domain-model">贫血模型</a>：DTO 被误当领域模型时长成的样子。</li></ul><h2 id="来源" tabindex="-1">来源 <a class="header-anchor" href="#来源" aria-label="Permalink to “来源”">​</a></h2><ul><li>[S5] Martin Fowler，《Patterns of Enterprise Application Architecture》，Addison-Wesley，2002。远程外观与数据传输对象的原始出处。</li><li>[S13] Chris Richardson，《Microservices Patterns》，Manning，2018。API 契约与 DTO 在微服务边界的实践口径。</li></ul>`,29)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};